const int MOD = 1000000007;

ll power(ll x, ll y) {
    ll result = 1;
    x %= MOD;
    while (y > 0) {
        if (y & 1) result = result * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return result;
}

int main() {
    int m;
    if (scanf("%d", &m) != 1) return 0;

    vector<int> mu(m + 1), primes;
    vector<bool> composite(m + 1, false);

    mu[1] = 1;
    for (int i = 2; i <= m; ++i) {
        if (!composite[i]) {
            primes.push_back(i);
            mu[i] = -1;
        }
        for (int prime : primes) {
            if (1LL * i * prime > m) break;
            composite[i * prime] = true;
            if (i % prime == 0) {
                mu[i * prime] = 0;
                break;
            }
            mu[i * prime] = -mu[i];
        }
    }

    vector<size_t> offset(m + 2, 0);
    for (int q = 1; q <= m; ++q) {
        offset[q + 1] = offset[q] + m / q + 1;
    }

    vector<int> coprimeCount(offset[m + 1], 0);

    for (int d = 1; d <= m; ++d) {
        if (mu[d] == 0) continue;
        for (int q = d; q <= m; q += d) {
            const size_t base = offset[q];
            const int limit = m / q;
            for (int x = 1; x <= limit; ++x) {
                coprimeCount[base + x] += mu[d] * (m / (x * d));
            }
        }
    }

    const ll inverseM = power(m, MOD - 2);
    vector<ll> f(m + 1, 0), pending(m + 1, 0);

    for (int i = 2; i <= m; ++i) {
        ll denominator = (1 - (m / i) * inverseM) % MOD;
        if (denominator < 0) denominator += MOD;

        f[i] = (pending[i] * inverseM + 1) % MOD;
        f[i] = f[i] * power(denominator, MOD - 2) % MOD;

        for (int q = 2; q <= m / i; ++q) {
            int target = i * q;
            ll contribution = f[i] * coprimeCount[offset[q] + i] % MOD;
            pending[target] += contribution;
            if (pending[target] >= MOD) pending[target] -= MOD;
        }
    }

    ll answer = 0;
    for (int i = 1; i <= m; ++i) {
        answer += f[i];
        if (answer >= MOD) answer -= MOD;
    }

    answer = (answer * inverseM + 1) % MOD;
